      { id: "comb-26", name: "Weapon Draw → Strike → Disarm", chain: "Empty-hand → weapon draw → weapon strike → opponent weapon → disarm → control", mechanics: "Seamless transition, weapon line control, leverage", safety: "Strict weapon control, tap system", focus: "Integration, timing", difficulty: "advanced" },
      { id: "comb-27", name: "Pressure Point → Joint Lock", chain: "Nerve strike → joint manipulation → control hold → release", mechanics: "Targeted disruption, leverage application, control", safety: "Strict control, anatomical knowledge", focus: "Precision, ethical application", difficulty: "advanced" },
      { id: "comb-28", name: "Flowing Angle Chain", chain: "Cartwheel approach → angular strike → spin exit → counter angle → reset", mechanics: "Flowing entry for surprise, angular exit for control", safety: "Master landing mechanics, use mats", focus: "Momentum control, spatial awareness", difficulty: "advanced" },
      { id: "comb-29", name: "Multiple Threat Response", chain: "Primary threat strike → angle change → secondary threat awareness → escape route", mechanics: "Prioritize, angle, assess, disengage", safety: "Clear space, avoid grappling", focus: "Spatial awareness, exit strategy", difficulty: "advanced" },
      { id: "comb-30", name: "Full System Flow", chain: "Shadow → partner → weapon → ground → multiple → escape → reset", mechanics: "Seamless integration of all ranges and tools", safety: "Progressive intensity, tap system", focus: "Holistic application, breath sync", difficulty: "advanced" }
